import { useState, useRef } from "react";
import { View, Text, TextInput, Pressable } from "react-native";

export default function App() {
  const [pw, setPw] = useState("");
  const [show, setShow] = useState(false);
  const passRef = useRef(null);

  return (
    <View>
      <TextInput
        testID="email" placeholder="Email" keyboardType="email-address" autoCapitalize="none"
        textContentType="emailAddress" returnKeyType="next"
        onSubmitEditing={() => passRef.current?.focus()}           // Enter -> sang ô kế
      />
      <TextInput
        ref={passRef} testID="pw" placeholder="Mật khẩu" value={pw} onChangeText={setPw}
        secureTextEntry={!show} textContentType="password" returnKeyType="done"
      />
      <Pressable testID="eye" onPress={() => setShow(!show)}><Text>{show ? "Ẩn" : "Hiện"}</Text></Pressable>
    </View>
  );
}

